import fs from 'node:fs';import vm from 'node:vm';import assert from 'node:assert/strict';import {test} from 'node:test';
const root=new URL('./',import.meta.url),c=vm.createContext({});const source=fs.readFileSync(new URL('../source/archive.js',root),'utf8');vm.runInContext(source,c);const expected=fs.readFileSync(new URL('expected.nes',root));
test('CRC values no longer read, stored, computed or compared in runtime source',()=>{assert.doesNotMatch(source,/verifyCRC|crcTable|packedCRC|\.crc\b|\bcrc\b|['"]CRC['"]/);for(const name of ['lzma.7z','lzma2.7z','lzma-header.7z','lzma2-header.7z']){const b=fs.readFileSync(new URL('archives/'+name,root));b[8]^=255;b[28]^=255;assert.deepEqual(Buffer.from(c.readSevenZip(b)),expected);}});
test('every stored CRC field can change without changing decoded bytes',()=>{const old=vm.createContext({});vm.runInContext(fs.readFileSync(new URL('references/crc-reference.js',root),'utf8'),old);const b=fs.readFileSync(new URL('archives/lzma.7z',root)),positions=[];const Reader=vm.runInContext('ArchiveReader',old),fixed=Reader.prototype.fixed;Reader.prototype.fixed=function(n){if(n===4)positions.push(this.bytes.byteOffset+this.pos-b.byteOffset);return fixed.call(this,n);};old.readSevenZip(b);assert.ok(positions.length>=3);for(const offset of [...positions]){const bad=Buffer.from(b);bad[offset]^=255;assert.deepEqual(Buffer.from(c.readSevenZip(bad)),expected);assert.throws(()=>old.readSevenZip(bad),/CRC/);}});
test('digest skipping preserves optional bitmap and inherited-substream layout',()=>{const R=vm.runInContext('ArchiveReader',c);for(const[bytes,count,defined,pos]of [[[1,1,2,3,4],1,true,5],[[0,128,1,2,3,4],1,true,6],[[0,0],1,false,2],[[1],0,false,1],[[0],0,false,1]]){const r=new R(Uint8Array.from(bytes));assert.equal(r.skipDigest(count),defined);assert.equal(r.pos,pos);}assert.throws(()=>new R(Uint8Array.of(1,0)).skipDigest(),/EOF/);});
